import itertools
P = {"Saltby": {"tea": 16, "grain": 58, "spice": 55, "iron": 49},
     "Oakhaven": {"tea": 45, "grain": 29, "spice": 22, "iron": 37},
     "Fennick": {"tea": 15, "grain": 20, "spice": 49, "iron": 59},
     "Rivermouth": {"tea": 12, "grain": 26, "spice": 56, "iron": 37}}
GOODS = ["tea","grain","spice","iron"]
TOWNS = list(P)
CAP, LAST = 25, 7

def idx(goods): return GOODS.index(goods)

# state: (town, gold, cargo-tuple). day handled layer by layer.
def closure(states, town):
    """apply any sequence of buys/sells in `town`; return set of new states"""
    states = set(states)
    changed = True
    iters = 0
    while changed and iters < 40:
        changed = False; iters += 1
        new = set()
        for (tn, gold, c) in states:
            if tn != town: continue
            tot = sum(c)
            for gi, g in enumerate(GOODS):
                p = P[town][g]
                # buy max affordable
                room = CAP - tot
                q = min(room, gold // p)
                if q > 0:
                    c2 = list(c); c2[gi] += q
                    ns = (tn, gold - p*q, tuple(c2))
                    if ns not in states: states.add(ns); new.add(ns); changed = True
                # sell all of good
                if c[gi] > 0:
                    c2 = list(c); c2[gi] = 0
                    ns = (tn, gold + p*c[gi], tuple(c2))
                    if ns not in states: states.add(ns); new.add(ns); changed = True
            # also partial buys/sells (qty other than max) may matter
            for gi, g in enumerate(GOODS):
                p = P[town][g]
                room = CAP - tot
                for q in range(1, min(room, gold//p)+1):
                    if q == min(room, gold//p): continue
                    c2 = list(c); c2[gi] += q
                    ns = (tn, gold - p*q, tuple(c2))
                    if ns not in states: states.add(ns)
                if c[gi] > 0:
                    for q in range(1, c[gi]):
                        c2 = list(c); c2[gi] = c[gi]-q
                        ns = (tn, gold + p*q, tuple(c2))
                        if ns not in states: states.add(ns)
                    # selling full is handled above
        if new and not changed: changed = True
    return states

best = 0
states = {("Saltby", 120, (0,0,0,0))}
for day in range(1, LAST+1):
    for town in TOWNS:
        sub = [s for s in states if s[0] == town]
        if sub:
            states = (states - set(sub)) | closure(sub, town)
    if day < LAST:
        moved = set()
        for (tn, gold, c) in states:
            for t2 in TOWNS:
                if t2 != tn:
                    moved.add((t2, gold, c))
        states |= moved
    if day == LAST:
        for (tn, gold, c) in states:
            if gold > best: best = gold
print("best final gold:", best)
