GOODS = ["tea","grain","spice","iron"]
TOWNS = list(P)
CAP, LAST = 25, 7

def better(d, key, gold):
    if key not in d or gold > d[key]:
        d[key] = gold

def closure(d, town):
    changed = True
    while changed:
        changed = False
        cur = dict(d)
        for (tn, c), gold in list(cur.items()):
            if tn != town: continue
            tot = sum(c)
            room = CAP - tot
            # buy max of each good
            for gi, g in enumerate(GOODS):
                p = P[town][g]
                q = min(room, gold // p)
                if q > 0:
                    c2 = list(c); c2[gi] += q
                    g2 = gold - p*q
                    if better(cur, (tn, tuple(c2)), g2):
                        d[(tn, tuple(c2))] = max(d.get((tn, tuple(c2)), -1), g2); changed = True
            # sell all of each good
            for gi, g in enumerate(GOODS):
                if c[gi] > 0:
                    c2 = list(c); c2[gi] = 0
                    g2 = gold + P[town][g]*c[gi]
                    if better(cur, (tn, tuple(c2)), g2):
                        d[(tn, tuple(c2))] = max(d.get((tn, tuple(c2)), -1), g2); changed = True
        d = cur
    return d

d = {("Saltby", (0,0,0,0)): 120}
t0 = time.time()
for day in range(1, LAST+1):
    for town in TOWNS:
        sub = {k: v for k, v in d.items() if k[0] == town}
        if sub:
            d = {k: v for k, v in d.items() if k[0] != town}
            d.update(closure(sub, town))
