        for (tn, c), gold in d.items():
            for t2 in TOWNS:
                if t2 != tn:
                    if better(moved, (t2, c), gold): pass
                    if (t2, c) not in moved or gold > moved[(t2, c)]: moved[(t2, c)] = gold
        for k, v in moved.items():
            if k not in d or v > d[k]: d[k] = v
    print("day", day, "states:", len(d), "max gold so far:", max(d.values()))
print("best final gold:", max(d.values()))
print("time:", round(time.time()-t0,1), "s")
