import json
from functools import lru_cache

WORLD = {"prices": {"Highcliff": {"fish": 26, "amber": 27, "wine": 20, "salt": 21}, "Thornwick": {"fish": 43, "amber": 45, "wine": 56, "salt": 39}, "Dunmere": {"fish": 54, "amber": 55, "wine": 30, "salt": 19}, "Greywater": {"fish": 23, "amber": 41, "wine": 32, "salt": 34}}, "capacity": 25, "last_day": 8}
TOWNS = list(WORLD["prices"])
GOODS = ["fish","amber","wine","salt"]
GOLD_CAP = 20000

# DP: state (day, town, gold, good, qty). gold capped. Prune: for each (day,town,good,qty) keep max gold.
# Actions on day < 8: choose next town != current, and before leaving sell s units (0..qty) of good,
# then buy b units of one good g2 (0..25-cargo_after_sell).
# On day 8: sell all, done.

# Represent as dict: (town, good, qty) -> max gold, per day.
state = {("Highcliff", None, 0): 250}

def expand(states, day):
    # returns dict of (town,good,qty)->gold for day+1
    out = {}
    for (town, good, qty), gold in states.items():
        for ntown in TOWNS:
            if ntown == town: continue
            # choose how much to sell in current town (0..qty)
            for s in range(0, qty+1):
                g2 = gold + s * WORLD["prices"][town][good]
                rem = qty - s
                # choose purchase: good g3, qty b (0..25-rem)
                for g3 in GOODS + [None]:
                    maxb = 25 - rem
                    if g3 is None:
                        bs = [0]
                    else:
                        price = WORLD["prices"][town][g3]
                        bmax = min(maxb, g2 // price)
                        # only consider buying full bmax or... any b could matter only via leftover gold;
                        # for given b, leftover = g2 - b*price. More b => more gold tied up but more cargo.
                        # Try all b values? b up to 25, fine but expensive. We'll try b in {bmax} plus a few.
                        bs = [bmax]
                    for b in bs:
                        g3left = g2 - b * WORLD["prices"][town].get(g3,0) if g3 else g2
                        newqty = rem + (b if g3 else 0)
                        if g3 and b == 0: g3 = None; 
                        if rem == 0 and g3 is None: key = (ntown, None, 0)
                        elif g3 is None and rem>0: key = (ntown, good, rem)
                        else:
                            # cargo may be mixed (good + g3) - we disallow mixing in this simplification
                            if rem > 0 and g3: continue
                            key = (ntown, g3, newqty)
                        if key not in out or out[key] < g3left:
                            if g3left <= GOLD_CAP:
                                out[key] = g3left
    return out

best = 0
for day in range(1, 9):
    if day < 8:
        state = expand(state, day)
    else:
        # final: sell all
        for (town, good, qty), gold in state.items():
            tot = gold + (qty * WORLD["prices"][town][good] if good else 0)
            best = max(best, tot)
        break
print("best final gold:", best)
