def cart_units(cargo):
    return sum(cargo.values())

def room(cargo):
    return CAP - cart_units(cargo)

def max_affordable(gold, good, town, maxqty):
    """How many units of `good` can be bought in `town` given gold and cart room."""
    price = P[town][good]
    by_gold = gold // price if price>0 else maxqty
    return max(0, min(maxqty, by_gold))

def buy_max(state, good, maxqty=None):
    """Buy as much of `good` as possible (bounded by gold + cart room)."""
    town = state["town"]
    if maxqty is None:
        maxqty = room(state["cargo"])
    qty = max_affordable(state["gold"], good, town, maxqty)
    if qty <= 0: return 0
    ok,_ = sim.apply_action(state, ("buy", good, qty))
    return qty if ok else 0

def sell_all(state, good):
    """Sell the entire held quantity of `good` in the current town."""
    held = state["cargo"].get(good, 0)
    if held <= 0: return 0
    ok,_ = sim.apply_action(state, ("sell", good, held))
